#include <cstdio>
#include <type_traits>

struct Base {
  template <class Self>
  int which(this Self&&) {
    return std::is_same_v<std::remove_cvref_t<Self>, Base> ? 1 : 2;
  }
};
struct Derived : Base {};

int main() {
  Derived d;
  Base& b = d;
  std::printf("%d %d\n", d.which(), b.which());
}

